    id: "econ-2024-ol-q16-a-i", topicId: "economics-3-5", conceptId: "why-world-population-grew",
    section: "B", questionRef: "2024 OL Q16(a)(i)",
    questionText: "Outline one reason why you think global population has grown so rapidly since 1804.",
    tariffModel: {"kind":"bestNofParts","notation":"1 @ 9","answer":1,"ofParts":9,"perPart":9}, totalMarks: 9,
