    section: "B", questionRef: "2024 OL Q16(a)(iii)",
    questionText: "Ireland’s population is ageing faster than anywhere else in Europe. Outline one economic effect this will have on the Irish government.",
    tariffModel: {"kind":"bestNofParts","notation":"1 @ 9","answer":1,"ofParts":5,"perPart":9}, totalMarks: 9,
